"""Revision 06: public route coverage, sourced indexes and missing journeys.
Executed by build.py with its shared page helpers. No network access at build time.
"""
import re
data_dir=R.parent/'revision-06'
directory=json.loads((data_dir/'directory.json').read_text())
issues=json.loads((data_dir/'issues.json').read_text())
reviews=json.loads((data_dir/'reviews.json').read_text())
current=json.loads((data_dir/'current-issue.json').read_text())
profile_ids=[82,73,54,346,472,337,165,62,149,179,257,171,457,36,46,39]
sample_slugs={809:'dokana',810:'kshanika',814:'drink'}
local_profiles={82:'poet-dokana.html',337:'poet-kshanika.html',257:'poet-drink.html',1:'editor-pradeep.html',43:'editor-paresh.html'}
for i,p in enumerate(current):
 p['id']=int(p['href'].split('=')[1]);p['title'],p['author']=p['heading'].split('\n\n',1)
 p['lang']='or' if i<5 else 'hi' if i<7 else 'en'
 p['label']={'or':'ଓଡ଼ିଆ','hi':'हिन्दी','en':'English'}[p['lang']]
 p['profile_id']=profile_ids[i]
 p['reader']='poem-'+sample_slugs[p['id']]+'.html' if p['id'] in sample_slugs else 'https://kabitalive.com/'+p['href']
 p['profile']=local_profiles.get(p['profile_id'],'https://kabitalive.com/contri-view.php?id='+str(p['profile_id']))
def current_rows():
 return '<div class="poem-list">'+''.join(f'<article class="poem-row" data-lang="{p["lang"]}" data-search="{e(p["title"]+" "+p["author"])}"><span class="number">{i:02d}</span><h3 class="{p["lang"]}" lang="{p["lang"]}"><a href="{p["reader"]}">{e(p["title"])}</a></h3><div class="byline row-author"><a href="{p["profile"]}">{e(p["author"])}</a><br><small>{p["label"]} · <a href="{p["reader"]}">{"Reading preview" if p["id"] in sample_slugs else "Original published poem ↗"}</a></small></div><a class="arrow" href="{p["reader"]}" aria-label="Read {e(p["title"])}">↗</a></article>' for i,p in enumerate(current,1))+'</div><p class="empty" id="empty-results" hidden>No poems match. Try another name or language.</p>'
current_note='<p class="reader-note">All 16 current-issue titles and credits are verified. Three poems open the designed reading preview; the others open the original published page. Full poem text has not been migrated.</p>'
page('issue-47.html','Issue 47',crumb('Current issue')+'<section class="issue-intro">'+cover(47)+'<div><span class="eyebrow">September 2026 · Issue 47</span><h1>Sixteen poems.<br>A shared horizon.</h1><p class="signature" lang="or">ମାଟିର ମହକ · ମନର ସ୍ୱର</p><p>Five in Odia. Two in Hindi. Nine in English.</p><p class="small muted">Proposed photographic cover · Generated artwork</p><div class="issue-actions">'+btn('Meet this issue’s poets','current-contributors.html',False)+'</div></div></section>'+filters()+current_rows()+current_note+'<div class="next-prev"><a href="archive.html">← All issues</a><a href="issue-46.html">Issue 46 →</a></div>','Current issue','Complete verified current-issue index: 16 poems in three languages.')
page('poems.html','Poems',head('The reading room','Find a poem.<br>Stay a little longer.','The complete September 2026 contents, with a path to the wider archive.')+'<div class="search-field"><label><span class="label">Search the current issue</span><input id="list-search" type="search" placeholder="Title or poet’s name"></label></div>'+filters()+current_rows()+current_note+btn('Browse every issue','archive.html',False),'Poems','Unicode search across all 16 current poem titles and authors.')
page('search.html','Search',head('A word can lead you somewhere','Follow a word.<br>Find a voice.','Search current poems by title or poet. For earlier work, explore the archive or the complete writer directory.')+'<div class="search-field"><label><span class="label">Search current poems and poets</span><input id="list-search" type="search" placeholder="Try ଦୋକାନ, memory, or a poet’s name"></label></div>'+filters()+current_rows()+current_note+'<div class="issue-actions">'+btn('All 427 writers','poets.html',False)+btn('All 47 issues','archive.html',False)+'</div>',desc='Useful search and no-results states with wider browsing paths.')
people_current=''.join(f'<a class="person" href="{p["profile"]}"><span class="initial" aria-hidden="true">{e("".join(w[0] for w in p["author"].split("/")[0].split()[:2]))}</span><span><h2>{e(p["author"])}</h2><span class="small muted">{p["label"]} · {e(p["title"])}</span></span></a>' for p in current)
page('current-contributors.html','Contributors · Issue 47',crumb('<a href="issue-47.html">Issue 47</a> / Contributors')+head('Sixteen voices','The voices gathered here.','Each name leads to the writer’s own page and contribution history.')+'<div class="two">'+people_current+'</div><p class="reader-note">Three contributor profiles and the editorial profiles have local design previews; other names retain their original profile links. Portraits will use approved photographs.</p>',active='Poets',desc='All 16 current contributors, linked to their profiles.')

# Names are preserved from the visible directory; do not infer language from script or name.
alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ'
directory_html=''
for letter in alphabet:
 entries=sorted([p for p in directory if p['name'][:1].upper()==letter],key=lambda x:x['name'].casefold())
 if not entries:continue
 directory_html+=f'<section class="directory-section" data-letter="{letter}" id="letter-{letter}"><h2>{letter}</h2><div class="directory-grid">'
 for p in entries:
  pid=int(p['url'].split('=')[1]);url=local_profiles.get(pid,p['url']);local=pid in local_profiles
  directory_html+=f'<a class="directory-entry" data-directory-name="{e(p["name"])}" href="{url}"><span>{e(p["name"])}</span><small>{"Profile preview" if local else "Original profile ↗"}</small></a>'
 directory_html+='</div></section>'
page('poets.html','Poets',head('The writers of Kabita Live','A gathering of voices.','Find a writer by name, in the original script or Roman spelling shown in the journal.')+'<div class="search-field"><label><span class="label">Find a writer</span><input id="directory-search" type="search" placeholder="Name in any script"></label></div><div class="alphabet" role="group" aria-label="Filter by first letter"><button data-letter-filter="all" aria-pressed="true">All</button>'+''.join(f'<button data-letter-filter="{x}" aria-pressed="false">{x}</button>' for x in alphabet)+'</div><p id="directory-status" role="status" class="small muted">427 entries</p>'+directory_html+'<p id="directory-empty" class="empty" hidden>No writers match. Choose All or try another spelling.</p><p class="reader-note">Source names and original profile links are preserved. Identical names with different source IDs remain separate until the editors verify them. Reading languages should be derived from verified contributions, not guessed from names.</p>','Poets','Complete public contributor index with working A–Z and Unicode search.')
for p in issues:
 parts=[x for x in p['label'].split('\n') if x.strip()]
 p['number']=int(re.search(r'\d+',p['title']).group());p['month']=parts[1];p['year']=parts[2]
 p['local']='issue-'+str(p['number'])+'.html' if p['number']>=45 else p['url']
issues.sort(key=lambda p:p['number'],reverse=True)
def issue_rows(year=None):
 selected=[p for p in issues if not year or p['year']==str(year)]
 return '<div class="issue-records">'+''.join(f'<a class="issue-record" data-issue-year="{p["year"]}" href="{p["local"]}"><span class="issue-number">{p["number"]:02d}</span><span><strong>{p["month"]} {p["year"]}</strong><small>Issue {p["number"]} · {"Design preview" if p["number"]>=45 else "Original issue ↗"}</small></span><span aria-hidden="true">↗</span></a>' for p in selected)+'</div>'
year_nav='<nav class="year-nav" aria-label="Archive by year">'+''.join(f'<a href="archive-{yr}.html">{yr}<small>{sum(p["year"]==str(yr) for p in issues)} issues</small></a>' for yr in range(2026,2021,-1))+'</nav>'
page('archive.html','Archive',head('November 2022 — September 2026','Every issue,<br>another beginning.','Forty-seven issues. A continuing conversation across the years.')+year_nav+'<div class="section-head"><h2>An issue, an opening.</h2><div class="filter" role="group" aria-label="Archive view"><button data-view="grid" aria-pressed="true">Covers</button><button data-view="list" aria-pressed="false">List</button></div></div>'+covercards()+'<section class="section"><div class="section-head"><h2>Through the years.</h2><label><span class="label">Filter by year</span><select id="archive-year"><option value="all">All years</option>'+''.join(f'<option>{yr}</option>' for yr in range(2026,2021,-1))+'</select></label></div>'+issue_rows()+'</section><p class="reader-note">All 47 issue numbers and dates were checked against the public archive. Three have local cover previews; older entries open the original issue. Historical artwork and full contents remain to be migrated.</p>','Archive','All 47 public issue records, working year filter and five year collections.')
for yr in range(2026,2021,-1):
 page(f'archive-{yr}.html',f'Archive · {yr}',crumb('<a href="archive.html">Archive</a> / '+str(yr))+head('A year in poetry',str(yr),'Month by month, the pages gather.')+year_nav+issue_rows(yr)+'<p class="reader-note">Issue dates and links are verified source records. Entries marked Original issue open the existing magazine.</p>','Archive',f'All verified issue records from {yr}.')

review_cards=''.join(f'<article class="review-list-entry"><span class="eyebrow">Book review</span><h2><a href="{("review.html" if i==0 else p["url"])}">{e(p["title"])}</a></h2><p>Review by {e(p["author"])}</p><a class="text-link" href="{("review.html" if i==0 else p["url"])}">{"Explore the reading layout" if i==0 else "Read the original review"} ↗</a></article>' for i,p in enumerate(reviews))
page('reviews.html','Book reviews',head('Books in conversation','The reading continues.','Eight reviews from the public catalogue, with each reviewer clearly credited.')+'<div class="two review-list">'+review_cards+'</div><p class="reader-note">Review titles and credits are source metadata. Original book covers will retain their own publisher artwork; magazine cover studies never substitute for a real book cover.</p>','Reviews','All eight listed book reviews, with verified article credits.')
page('review.html','Toshali Anthology of Love Poems 2026',crumb('<a href="reviews.html">Book reviews</a> / Reading preview')+head('Book review','Toshali Anthology of<br>Love Poems 2026','Review by Sarita Prusty')+'<div class="side-layout"><article class="prose"><span class="eyebrow">Editorial synopsis · Design preview</span><p>This review considers the anthology’s many expressions of love, including companionship, memory and devotion. It draws attention to the collection’s range of voices and poetic forms.</p><p class="reader-note">This short synopsis demonstrates the reading layout. The complete published review has not been reproduced here.</p>'+btn('Read the original review','https://kabitalive.com/bookview.php?id=11',False)+'<h2 style="margin-top:45px">A book’s own identity.</h2><p>The finished page pairs the complete review with the actual publisher’s cover, separate credits for the reviewer and book creators, and verified publication details.</p></article><aside class="side-panel"><span class="eyebrow">About the book</span><h2>Toshali Anthology of Love Poems 2026</h2><dl class="meta-list"><dt>Reviewer</dt><dd>Sarita Prusty</dd><dt>Editors, as credited in the review</dt><dd>Pradeep Biswal<br>Paresh Patnaik<br>Namita Rani Panda</dd><dt>Publisher / ISBN / cover</dt><dd>To be verified before publication</dd></dl><a class="text-link" href="reviews.html">All book reviews ↗</a></aside></div>','Reviews','Sourced review identity, short synopsis and separate book metadata.')

