for slug,name,role,initial,pid,bio in team:
 work='<h2>A voice across the pages.</h2><a class="contribution-row" href="https://kabitalive.com/poemview.php?id=542"><span><h3>A Poet Has No Land</h3><small>Issue 30 · April 2025 · Original poem ↗</small></span></a>' if pid==1 else '<div class="notice">The existing managing-editor profile link returned to the homepage during the audit. Biography and contributions need verification before migration.</div>'
 page(f'editor-{slug}.html',name,crumb('<a href="editorial-team.html">Editorial team</a> / '+name)+f'<section class="writer-hero"><div class="writer-portrait"><span class="initial" role="img" aria-label="Initials; portrait pending approval">{initial}</span><p>Approved portrait pending</p></div><div><span class="eyebrow">{role} · Kabita Live</span><h1>{name}</h1><p class="writer-bio">{bio}</p><a class="text-link" href="mailto:kabitaliveweb@gmail.com">Write to the editorial desk ↗</a></div></section><section class="writer-work">{work}</section><a class="text-link" href="editorial-team.html">← Editorial team</a>','About',role+' profile, biography status and contribution history.')
page('about.html','About',head('Odia roots. Many voices.','A familiar name.<br>A living literary home.','A monthly journal for original poetry, translations and the readers who give poems another life.')+'<div class="side-layout"><div class="prose"><h2 class="or" lang="or">ମାଟିର ମହକ · ମନର ସ୍ୱର</h2><p>The fragrance of earth. The voice of the heart.</p><p>Odia gives the journal its visual centre. Hindi and English belong alongside it, with equal care for their words, their writers and their readers.</p><h2>Room for another voice.</h2><p>The existing editorial mission welcomes original poetry and translation, encourages younger voices and seeks readers across places and generations.</p><p><em>“Poetry is an echo, asking a shadow to dance.”</em></p><h2>A considered conversation</h2><p>Send poems and private queries by email. Reading responses are reviewed before appearing; they do not publish immediately.</p><a class="text-link" href="feedback.html">Reader letters and responses ↗</a><p class="reader-note">Proposed introduction informed by the <a class="text-link" href="https://kabitalive.com/about.php">existing About page</a>. Editorial review is required before launch.</p></div><aside class="side-panel"><span class="eyebrow">The editorial desk</span><h2>Pradeep Biswal</h2><p>Editor</p><a class="text-link" href="editor-pradeep.html">Profile ↗</a><h2 style="margin-top:28px">Paresh Kumar Pattnaik</h2><p>Managing Editor</p><a class="text-link" href="editor-paresh.html">Profile ↗</a><div class="issue-actions">'+btn('Meet the editorial team','editorial-team.html',False)+'</div></aside></div>','About','Mission, language hierarchy, moderated responses and linked editors.')

